import random

P = {"sunny": {"sunny": 0.8, "rainy": 0.2}, "rainy": {"sunny": 0.4, "rainy": 0.6}}
random.seed(24)
state, counts = "sunny", {"sunny": 0, "rainy": 0}
for _ in range(200_000):
    state = random.choices(list(P[state]), weights=list(P[state].values()))[0]
    counts[state] += 1
print({k: round(v / 200_000, 3) for k, v in counts.items()}, "-> stationary: sunny 2/3, rainy 1/3")

text = "the cat sat on the mat the cat ate the rat".split()             # a Markov chain of words
nxt = {}
for a, b in zip(text, text[1:]):
    nxt.setdefault(a, []).append(b)
word, out = "the", ["the"]
for _ in range(8):
    word = random.choice(nxt.get(word, text)); out.append(word)
print(" ".join(out))

import random, math, statistics

random.seed(25)
def walk(n):
    return sum(random.choice((-1, 1)) for _ in range(n))

for n in (100, 400, 1600):
    ends = [walk(n) for _ in range(2000)]
    print(f"{n:5d} steps: typical distance {statistics.pstdev(ends):6.1f}   sqrt(n) = {math.sqrt(n):5.1f}")

def returns(n):                                             # does a 1-D walk revisit its start within n steps?
    x = 0
    for _ in range(n):
        x += random.choice((-1, 1))
        if x == 0:
            return True
    return False
print(sum(returns(2000) for _ in range(500)) / 500, "of walks returned to the start within 2000 steps")

import math, random

random.seed(26)
def target(x):                                    # unnormalized: a mixture of two bumps
    return math.exp(-0.5 * (x + 2) ** 2) + 0.5 * math.exp(-0.5 * ((x - 3) / 0.7) ** 2)

x, samples = 0.0, []
for step in range(200_000):
    proposal = x + random.gauss(0, 1.5)
    if random.random() < min(1, target(proposal) / target(x)):
        x = proposal
    if step > 5_000:
        samples.append(x)

print("share of samples near the left bump:", round(sum(s < 0.5 for s in samples) / len(samples), 3))
print("expected: about", round(1 / 1.35, 3))

states = ("rainy", "sunny")
start = {"rainy": 0.6, "sunny": 0.4}
trans = {"rainy": {"rainy": 0.7, "sunny": 0.3}, "sunny": {"rainy": 0.4, "sunny": 0.6}}
emit = {"rainy": {"walk": 0.1, "shop": 0.4, "clean": 0.5}, "sunny": {"walk": 0.6, "shop": 0.3, "clean": 0.1}}

def viterbi(obs):
    best = [{s: (start[s] * emit[s][obs[0]], [s]) for s in states}]
    for o in obs[1:]:
        best.append({s: max((best[-1][p][0] * trans[p][s] * emit[s][o], best[-1][p][1] + [s]) for p in states)
                     for s in states})
    return max(best[-1].values())

prob, path = viterbi(["walk", "shop", "clean"])
print(path, round(prob, 5))
